    if (regionCell) {
      const rowRegion = regionCell.textContent.toLowerCase().trim();

      // Show the row if "all" is selected or if the region matches; otherwise hide it
      if (selectedRegion === 'all' || selectedRegion === '' || rowRegion === selectedRegion) {
