import React, { useState, useMemo } from 'react';

// Mock data for warranty claims
const mockClaimsData = [
  { id: 'WC-1001', customer: 'Alice Johnson', product: 'Laptop Pro 15', status: 'Approved', amount: 1200, date: '2023-10-01' },
  { id: 'WC-1002', customer: 'Bob Smith', product: 'Wireless Mouse', status: 'Pending', amount: 45, date: '2023-10-15' },
  { id: 'WC-1003', customer: 'Charlie Brown', product: 'Desktop PC', status: 'Rejected', amount: 850, date: '2023-09-20' },
  { id: 'WC-1004', customer: 'Diana Prince', product: 'Smartphone X', status: 'Approved', amount: 600, date: '2023-10-10' },
  { id: 'WC-1005', customer: 'Evan Wright', product: 'Noise Cancelling Headphones', status: 'Pending', amount: 250, date: '2023-10-22' },
];

const WarrantyClaims = () => {
  // State for filtering
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');

  // State for sorting
  const [sortConfig, setSortConfig] = useState({ key: 'date', direction: 'descending' });

  // Handle sorting logic
  const handleSort = (key) => {
    let direction = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  // Process data (Filter -> Sort)
  const processedClaims = useMemo(() => {
    let filteredData = [...mockClaimsData];

    // 1. Apply Text Filter (Search by customer or product)
    if (searchTerm) {
      const lowerCaseSearch = searchTerm.toLowerCase();
      filteredData = filteredData.filter(
        (claim) =>
          claim.customer.toLowerCase().includes(lowerCaseSearch) ||
          claim.product.toLowerCase().includes(lowerCaseSearch) ||
          claim.id.toLowerCase().includes(lowerCaseSearch)
      );
    }

    // 2. Apply Status Filter
    if (statusFilter !== 'All') {
      filteredData = filteredData.filter((claim) => claim.status === statusFilter);
    }

    // 3. Apply Sorting
    if (sortConfig !== null) {
      filteredData.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === 'ascending' ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === 'ascending' ? 1 : -1;
        }
        return 0;
      });
    }

    return filteredData;
  }, [searchTerm, statusFilter, sortConfig]);

  // Helper for rendering sort arrows
  const getSortIndicator = (columnKey) => {
    if (sortConfig?.key === columnKey) {
      return sortConfig.direction === 'ascending' ? ' ▲' : ' ▼';
    }
    return '';
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif', maxWidth: '900px', margin: '0 auto' }}>
      <h2>Warranty Claims Dashboard</h2>

      {/* Filters Section */}
      <div style={{ display: 'flex', gap: '15px', marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Search by ID, Customer, or Product..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ padding: '8px', flex: 1, borderRadius: '4px', border: '1px solid #ccc' }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        >
          <option value="All">All Statuses</option>
          <option value="Approved">Approved</option>
          <option value="Pending">Pending</option>
          <option value="Rejected">Rejected</option>
        </select>
      </div>

      {/* Data Table */}
      <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
        <thead>
          <tr style={{ backgroundColor: '#f4f4f4', borderBottom: '2px solid #ddd' }}>
            <th onClick={() => handleSort('id')} style={thStyle}>
              Claim ID {getSortIndicator('id')}
            </th>
            <th onClick={() => handleSort('customer')} style={thStyle}>
              Customer {getSortIndicator('customer')}
            </th>
            <th onClick={() => handleSort('product')} style={thStyle}>
              Product {getSortIndicator('product')}
            </th>
            <th onClick={() => handleSort('date')} style={thStyle}>
              Date {getSortIndicator('date')}
            </th>
            <th onClick={() => handleSort('amount')} style={thStyle}>
              Amount ($) {getSortIndicator('amount')}
            </th>
            <th onClick={() => handleSort('status')} style={thStyle}>
              Status {getSortIndicator('status')}
            </th>
          </tr>
        </thead>
        <tbody>
          {processedClaims.length > 0 ? (
            processedClaims.map((claim) => (
              <tr key={claim.id} style={{ borderBottom: '1px solid #eee' }}>
                <td style={tdStyle}>{claim.id}</td>
                <td style={tdStyle}>{claim.customer}</td>
                <td style={tdStyle}>{claim.product}</td>
                <td style={tdStyle}>{claim.date}</td>
                <td style={tdStyle}>${claim.amount.toFixed(2)}</td>
                <td style={tdStyle}>
                  <span style={getStatusStyle(claim.status)}>{claim.status}</span>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="6" style={{ textAlign: 'center', padding: '20px' }}>
                No claims found matching your filters.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

// Inline styles for simplicity
const thStyle = {
  padding: '12px',
  cursor: 'pointer',
  userSelect: 'none',
};

const tdStyle = {
  padding: '12px',
};

const getStatusStyle = (status) => {
  const baseStyle = { padding: '4px 8px', borderRadius: '12px', fontSize: '0.85em', fontWeight: 'bold' };
  switch (status) {
    case 'Approved':
      return { ...baseStyle, backgroundColor: '#d4edda', color: '#155724' };
    case 'Pending':
      return { ...baseStyle, backgroundColor: '#fff3cd', color: '#856404' };
    case 'Rejected':
      return { ...baseStyle, backgroundColor: '#f8d7da', color: '#721c24' };
    default:
      return baseStyle;
  }
};

