import React, { useState, useEffect } from 'react';

export default function WarrantyDashboard() {
  const [warranties, setWarranties] = useState([]);
  const [filter, setFilter] = useState('All');
  const [loading, setLoading] = useState(false);

  // Re-fetch data whenever the filter state changes
  useEffect(() => {
    fetchWarranties();
  }, [filter]);

  const fetchWarranties = async () => {
    setLoading(true);
    try {
      const response = await fetch(`http://localhost:5000/api/warranties?status=${filter}`);
      const data = await response.json();
      setWarranties(data);
    } catch (error) {
      console.error('Error fetching warranties:', error);
    }
    setLoading(false);
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'Segoe UI, Tahoma, Geneva, Verdana, sans-serif', maxWidth: '900px', margin: '0 auto' }}>
      <h2 style={{ color: '#2c3e50' }}>Warranty Dashboard</h2>

      {/* Filter Controls */}
      <div style={{ marginBottom: '25px' }}>
        <label htmlFor="statusFilter" style={{ marginRight: '10px', fontWeight: '600' }}>Filter by Status: </label>
        <select 
          id="statusFilter" 
          value={filter} 
          onChange={(e) => setFilter(e.target.value)}
          style={{ padding: '8px 12px', borderRadius: '5px', border: '1px solid #ced4da', cursor: 'pointer' }}
        >
          <option value="All">All</option>
          <option value="Active">Active</option>
          <option value="Expired">Expired</option>
          <option value="Pending">Pending</option>
        </select>
      </div>

      {/* Data Visualization */}
      {loading ? (
        <p style={{ color: '#6c757d' }}>Loading warranty data...</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', boxShadow: '0 4px 6px rgba(0,0,0,0.05)', backgroundColor: '#fff' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8f9fa', textAlign: 'left' }}>
              <th style={thStyle}>ID</th>
              <th style={thStyle}>Product</th>
              <th style={thStyle}>Customer</th>
              <th style={thStyle}>Expiration Date</th>
              <th style={thStyle}>Status</th>
            </tr>
          </thead>
          <tbody>
            {warranties.length > 0 ? (
              warranties.map((w) => (
                <tr key={w.id} style={{ borderBottom: '1px solid #e9ecef' }}>
                  <td style={tdStyle}>#{w.id}</td>
                  <td style={tdStyle}><strong>{w.product}</strong></td>
                  <td style={tdStyle}>{w.customer}</td>
                  <td style={tdStyle}>{w.expirationDate}</td>
                  <td style={tdStyle}>
                    <span style={{
                      padding: '5px 10px',
                      borderRadius: '15px',
                      fontSize: '0.85em',
                      fontWeight: 'bold',
                      color: w.status === 'Pending' ? '#856404' : '#fff',
                      backgroundColor: w.status === 'Active' ? '#28a745' : w.status === 'Expired' ? '#dc3545' : '#ffc107'
                    }}>
                      {w.status}
                    </span>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" style={{ textAlign: 'center', padding: '30px', color: '#6c757d' }}>
                  No warranties match the selected filter.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      )}
    </div>
  );
}

